use base64::{engine::general_purpose::STANDARD, Engine as _};
use std::{fs, path::{Path, PathBuf}};

const ICON_BASE64: &str = "";

fn ensure_windows_icon() {
    let manifest_dir = std::env::var("CARGO_MANIFEST_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|_| PathBuf::from("."));
    let icon_dir = manifest_dir.join("icons");
    let icon_path = icon_dir.join("icon.ico");

    if icon_path.exists() {
        return;
    }

    fs::create_dir_all(&icon_dir).expect("failed to create Tauri icon directory");
    let bytes = STANDARD.decode(ICON_BASE64).expect("failed to decode embedded Zaxis KDP icon");
    fs::write(icon_path, bytes).expect("failed to write embedded Zaxis KDP icon");
}

fn main() {
    ensure_windows_icon();
    tauri_build::build()
}
